)

type Store struct {
	mu     sync.Mutex
	counts map[string]int64
}

func NewStore() *Store {
	return &Store{
		counts: map[string]int64{
			"info":  0,
			"warn":  0,
			"error": 0,
		},
	}
}

func (s *Store) Increment(level string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.counts[level]++
}

