package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestPostLogsAccepted(t *testing.T) {
	server := newServer()

	body := `{"level": "info", "message": "started"}`
	req := httptest.NewRequest(http.MethodPost, "/logs", nil)
	req.Body = http.NoBody // We'll set body via httptest.NewRequest with body
	req = httptest.NewRequest(http.MethodPost, "/logs", nil)
	// Actually create request with body
	req, _ = http.NewRequest(http.MethodPost, "/logs", nil)
	// Better approach:
	req = httptest.NewRequest(http.MethodPost, "/logs", nil)
	// Let's do it properly
	req = httptest.NewRequest(http.MethodPost, "/logs", nil)

	// Correct way:
	req = httptest.NewRequest(http.MethodPost, "/logs", nil)

	// Use strings.NewReader
	import "strings"
	req = httptest.NewRequest(http.MethodPost, "/logs", strings.NewReader(body))

	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusAccepted {
		t.Errorf("expected 202, got %d", w.Code)
	}
}

func TestPostLogsBadLevel(t *testing.T) {
	server := newServer()

	body := `{"level": "bogus", "message": "x"}`
	req := httptest.NewRequest(http.MethodPost, "/logs", strings.NewReader(body))
	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusBadRequest {
		t.Errorf("expected 400, got %d", w.Code)
	}
}

func TestPostLogsEmptyMessage(t *testing.T) {
	server := newServer()

	body := `{"level": "error", "message": ""}`
	req := httptest.NewRequest(http.MethodPost, "/logs", strings.NewReader(body))
	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusBadRequest {
		t.Errorf("expected 400, got %d", w.Code)
	}
}

func TestGetStats(t *testing.T) {
	server := newServer()

	// First, post some logs
	testCases := []struct {
		level   string
		message string
	}{
		{"info", "first"},
		{"info", "second"},
		{"warn", "warning"},
		{"error", "error"},
	}

	for _, tc := range testCases {
		body, _ := json.Marshal(map[string]string{"level": tc.level, "message": tc.message})
		req := httptest.NewRequest(http.MethodPost, "/logs", strings.NewReader(string(body)))
		w := httptest.NewRecorder()
		server.ServeHTTP(w, req)
		if w.Code != http.StatusAccepted {
			t.Fatalf("failed to post log: %d", w.Code)
		}
	}

	// Now get stats
	req := httptest.NewRequest(http.MethodGet, "/logs/stats", nil)
	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected 200, got %d", w.Code)
	}

	var resp statsResponse
	if err := json.NewDecoder(w.Body).Decode(&resp); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}

	expected := map[string]int64{"info": 2, "warn": 1, "error": 1}
	for k, v := range expected {
		if resp.Counts[k] != v {
			t.Errorf("counts[%s] = %d, want %d", k, resp.Counts[k], v)
		}
	}
	// Ensure all three keys present
	for _, k := range []string{"info", "warn", "error"} {
		if _, ok := resp.Counts[k]; !ok {
			t.Errorf("missing key %s in counts", k)
		}
	}
}

